python3 - <<'EOF'
import re,io
p='tests/PostExcerpt.test.ts'
s=open(p).read()
s=s.replace("""  let http: TestApp
  let author: UserRecord

  beforeAll(async () => {
    http = await TestApp.fromApp(app)
  })

  beforeEach(async () => {
    await resetDatabase()
    author = (await User.create({
      name: 'Excerpt Writer',
      email: 'writer@example.com',
      password: 'secret',
    })) as UserRecord
  })""","""  let http: TestApp
  // Signed in as the author, with session + CSRF cookies primed — the
  // mutating routes sit behind both.
  let asAuthor: TestApp
  let author: UserRecord

  beforeAll(async () => {
    http = await TestApp.fromApp(app)
  })

  beforeEach(async () => {
    await resetDatabase()
    author = (await User.create({
      name: 'Excerpt Writer',
      email: 'writer@example.com',
      password: 'secret',
    })) as UserRecord
    asAuthor = (await http.actingAs(author).withCsrf()).json()
  })""")
s=s.replace("http\n      .actingAs(author)\n      .json()\n      .","asAuthor\n      .")
s=s.replace("http.actingAs(author).json().","asAuthor.")
open(p,'w').write(s)
EOF
grep -n "asAuthor\|http\." tests/PostExcerpt.test.ts
